package com.bank.payaudit;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class SameSalaryDemo {
    private static final Logger log = Logger.getLogger("PayAudit");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", new BigDecimal("800000")),
            new Employee("Amit", new BigDecimal("800000")),   // same as Rajesh
            new Employee("Priya", new BigDecimal("800000")),  // same as both
            new Employee("Neha", new BigDecimal("600000")));
        PayAuditService service = new PayAuditService();

        service.sameSalaryPairs(staff).forEach(p ->
            log.info(() -> p[0] + " & " + p[1] + " share a salary"));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final BigDecimal salary;
        Employee(String name, BigDecimal salary) { this.name = name;
        this.salary = salary; }
    String getName() { return name; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/PayAuditService.java ───
class PayAuditService {
    List<String[]> sameSalaryPairs(List<Employee> staff) {
        Map<BigDecimal, List<Employee>> bySalary = staff.stream()
            .collect(groupingBy(Employee::getSalary));        // bucket by salary
        List<String[]> pairs = new ArrayList<>();
        for (List<Employee> group : bySalary.values()) {
            if (group.size() < 2) continue;                   // only shared salaries
            for (int i = 0; i < group.size(); i++) {
                for (int j = i + 1; j < group.size(); j++) {  // unique pairs, no self-pair
                    pairs.add(new String[]{group.get(i).getName(), group.get(j).getName()});
                }
            }
        }
        return pairs;
    }
}
